        fn constant_float(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> Option<f64> {
            match expr {
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Float(value),
                    ..
                } => Some(*value),
                lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings.get(name)? {
                    AggregateBinding::Float(value) => Some(*value),
                    _ => None,
                },
                lucid_syntax::Expr::Index { value, index, .. } => {
                    if let Some(AggregateBinding::Float(value)) =
                        aggregate_expr_binding(expr, aggregate_bindings)
                    {
                        Some(value)
                    } else if let Some(AggregateElement::Aggregate(AggregateBinding::Float(
                        value,
                    ))) = mixed_record_element(value, index, aggregate_bindings)
                    {
                        Some(*value)
                    } else if let Some(values) = constant_float_list(value, aggregate_bindings) {
                        let selected = select_constant_index(values.len(), constant_index(index)?)?;
                        values.get(selected).copied()
                    } else if let Some(values) = constant_float_record(value, aggregate_bindings) {
                        let selected = select_constant_index(values.len(), constant_index(index)?)?;
                        values.get(selected).copied()
                    } else {
                        if let Some(index) = constant_string(index, aggregate_bindings) {
                            let entries = constant_string_float_dict(value, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else if let Some(index) = constant_singleton(index, aggregate_bindings) {
                            let entries = constant_singleton_float_dict(value, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else if let Some(entries) = constant_float_dict(value, aggregate_bindings)
                        {
                            let index = constant_float(index, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else {
                            let entries = constant_int_float_dict(value, aggregate_bindings)?;
                            let index = constant_index(index)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        }
                    }
                }
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Pos,
                    expr,
                    ..
                } => constant_float(expr, aggregate_bindings),
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Neg,
                    expr,
                    ..
                } => Some(-constant_float(expr, aggregate_bindings)?),
                _ => None,
            }
        }
