        fn constant_singleton(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> Option<SingletonBinding> {
            match expr {
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::None,
                    ..
                } => Some(SingletonBinding::None),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Ellipsis,
                    ..
                } => Some(SingletonBinding::Ellipsis),
                lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings.get(name)? {
                    AggregateBinding::None => Some(SingletonBinding::None),
                    AggregateBinding::Ellipsis => Some(SingletonBinding::Ellipsis),
                    _ => None,
                },
                lucid_syntax::Expr::Index { value, index, .. } => {
                    if let Some(AggregateBinding::None | AggregateBinding::Ellipsis) =
                        aggregate_expr_binding(expr, aggregate_bindings)
                    {
                        match aggregate_expr_binding(expr, aggregate_bindings)? {
                            AggregateBinding::None => Some(SingletonBinding::None),
                            AggregateBinding::Ellipsis => Some(SingletonBinding::Ellipsis),
                            _ => None,
                        }
                    } else if let Some(AggregateElement::Aggregate(
                        AggregateBinding::None | AggregateBinding::Ellipsis,
                    )) = mixed_record_element(value, index, aggregate_bindings)
                    {
                        match mixed_record_element(value, index, aggregate_bindings)? {
                            AggregateElement::Aggregate(AggregateBinding::None) => {
                                Some(SingletonBinding::None)
                            }
                            AggregateElement::Aggregate(AggregateBinding::Ellipsis) => {
                                Some(SingletonBinding::Ellipsis)
                            }
                            _ => None,
                        }
                    } else if let Some(values) = constant_singleton_list(value, aggregate_bindings)
                    {
                        let selected = select_constant_index(values.len(), constant_index(index)?)?;
                        values.get(selected).copied()
                    } else if let Some(values) =
                        constant_singleton_record(value, aggregate_bindings)
                    {
                        let selected = select_constant_index(values.len(), constant_index(index)?)?;
                        values.get(selected).copied()
                    } else {
                        if let Some(entries) = constant_singleton_dict(value, aggregate_bindings) {
                            let index = constant_singleton(index, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else if let Some(entries) =
                            constant_string_singleton_dict(value, aggregate_bindings)
                        {
                            let index = constant_string(index, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else if let Some(entries) =
                            constant_float_singleton_dict(value, aggregate_bindings)
                        {
                            let index = constant_float(index, aggregate_bindings)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        } else {
                            let entries = constant_int_singleton_dict(value, aggregate_bindings)?;
                            let index = constant_index(index)?;
                            entries
                                .iter()
                                .find_map(|(key, value)| (key == &index).then_some(*value))
                        }
                    }
                }
                _ => None,
            }
        }
        fn constant_singleton_list(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> Option<Vec<SingletonBinding>> {
            match expr {
                lucid_syntax::Expr::List { elements, .. } => elements
                    .iter()
                    .map(|element| constant_singleton(element, aggregate_bindings))
                    .collect(),
                lucid_syntax::Expr::Record { .. } => {
                    constant_singleton_record(expr, aggregate_bindings)
                }
                lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings.get(name)? {
                    AggregateBinding::SingletonList(values)
                    | AggregateBinding::SingletonRecord(values) => Some(values.clone()),
                    _ => None,
                },
                lucid_syntax::Expr::Call { .. } => {
                    constant_singleton_dict_view_list(expr, aggregate_bindings)
                }
                _ => None,
            }
        }
