        fn constant_singleton_record(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> Option<Vec<SingletonBinding>> {
            match expr {
                lucid_syntax::Expr::Record { fields, .. } => fields
                    .iter()
                    .map(|(name, field)| {
                        if name.is_some() {
                            None
                        } else {
                            constant_singleton(field, aggregate_bindings)
                        }
                    })
                    .collect(),
                lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings.get(name)? {
                    AggregateBinding::SingletonRecord(values) => Some(values.clone()),
                    _ => None,
                },
                _ => None,
            }
        }
        fn constant_singleton_dict(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> Option<Vec<(SingletonBinding, SingletonBinding)>> {
            match expr {
                lucid_syntax::Expr::Dict { entries, .. } => entries
                    .iter()
                    .map(|(key, value)| {
                        Some((
                            constant_singleton(key, aggregate_bindings)?,
                            constant_singleton(value, aggregate_bindings)?,
                        ))
                    })
                    .collect(),
                lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings.get(name)? {
                    AggregateBinding::SingletonDict(entries) => Some(entries.clone()),
                    _ => None,
                },
                _ => None,
            }
        }
        fn constant_binding_candidate(
            expr: &lucid_syntax::Expr,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
        ) -> bool {
            match expr {
                lucid_syntax::Expr::List { .. }
                | lucid_syntax::Expr::Set { .. }
                | lucid_syntax::Expr::Record { .. }
                | lucid_syntax::Expr::Literal {
                    value:
                        lucid_syntax::LiteralValue::Str(_)
                        | lucid_syntax::LiteralValue::Bytes(_)
                        | lucid_syntax::LiteralValue::Float(_)
                        | lucid_syntax::LiteralValue::None
                        | lucid_syntax::LiteralValue::Ellipsis,
                    ..
                } => true,
                lucid_syntax::Expr::Dict { .. } => true,
                lucid_syntax::Expr::Unary { expr, .. } => {
                    constant_float(expr, aggregate_bindings).is_some()
                }
                lucid_syntax::Expr::Call { .. } => {
                    const_range_values(expr).is_some()
                        || constant_string_list(expr, aggregate_bindings).is_some()
                }
                lucid_syntax::Expr::Ident { name, .. } => aggregate_bindings.contains_key(name),
                _ => false,
            }
        }
        fn lower(
            expr: &lucid_syntax::Expr,
            bindings: &HashMap<String, ValueId>,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> Result<ValueId, LowerError> {
            let result = |next: &mut u32| {
                let value = ValueId(*next);
                *next += 1;
                value
            };
            match expr {
                lucid_syntax::Expr::Ident { name, .. } => bindings
                    .get(name)
                    .copied()
                    .ok_or(LowerError::UnsupportedExpression),
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Attribute { attr, .. }
                            if attr == "startswith" || attr == "endswith"
                    ) && args.len() == 1 =>
                {
                    let lucid_syntax::Expr::Attribute { value, attr, .. } = func.as_ref() else {
                        unreachable!();
                    };
                    let receiver = constant_string(value, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let needle = constant_string(&args[0].value, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let value = if attr == "startswith" {
                        receiver.starts_with(&needle)
                    } else {
                        receiver.ends_with(&needle)
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "len"
                    ) && args.len() == 1 =>
                {
                    let length = match &args[0].value {
                        expr if constant_string(expr, aggregate_bindings).is_some() => {
                            constant_string(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .chars()
                                .count()
                        }
                        expr if constant_string_list(expr, aggregate_bindings).is_some() => {
                            constant_string_list(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_list(expr, aggregate_bindings).is_some() => {
                            constant_float_list(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_list(expr, aggregate_bindings).is_some() => {
                            constant_singleton_list(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_string_set(expr, aggregate_bindings).is_some() => {
                            constant_string_set(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_set(expr, aggregate_bindings).is_some() => {
                            constant_float_set(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_set(expr, aggregate_bindings).is_some() => {
                            constant_singleton_set(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_string_dict(expr, aggregate_bindings).is_some() => {
                            constant_string_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_string_int_dict(expr, aggregate_bindings).is_some() => {
                            constant_string_int_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_string_float_dict(expr, aggregate_bindings).is_some() => {
                            constant_string_float_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_string_singleton_dict(expr, aggregate_bindings)
                            .is_some() =>
                        {
                            constant_string_singleton_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_int_string_dict(expr, aggregate_bindings).is_some() => {
                            constant_int_string_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_dict(expr, aggregate_bindings).is_some() => {
                            constant_float_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_int_float_dict(expr, aggregate_bindings).is_some() => {
                            constant_int_float_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_int_singleton_dict(expr, aggregate_bindings).is_some() => {
                            constant_int_singleton_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_int_dict(expr, aggregate_bindings).is_some() => {
                            constant_float_int_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_string_dict(expr, aggregate_bindings).is_some() => {
                            constant_float_string_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_float_singleton_dict(expr, aggregate_bindings)
                            .is_some() =>
                        {
                            constant_float_singleton_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_dict(expr, aggregate_bindings).is_some() => {
                            constant_singleton_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_string_dict(expr, aggregate_bindings)
                            .is_some() =>
                        {
                            constant_singleton_string_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_int_dict(expr, aggregate_bindings).is_some() => {
                            constant_singleton_int_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        expr if constant_singleton_float_dict(expr, aggregate_bindings)
                            .is_some() =>
                        {
                            constant_singleton_float_dict(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .len()
                        }
                        lucid_syntax::Expr::List { elements, .. } => {
                            for element in elements {
                                let _ = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                            }
                            elements.len()
                        }
                        lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let _ = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                            }
                            elements.len()
                        }
                        lucid_syntax::Expr::Dict { entries, .. } => {
                            for (key, value) in entries {
                                let _ =
                                    lower(key, bindings, aggregate_bindings, instructions, next)?;
                                let _ =
                                    lower(value, bindings, aggregate_bindings, instructions, next)?;
                            }
                            entries.len()
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let _ =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                            }
                            fields.len()
                        }
                        expr if constant_dict_view_len(expr, aggregate_bindings).is_some() => {
                            constant_dict_view_len(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                        }
                        lucid_syntax::Expr::Call { .. } => const_range_values(&args[0].value)
                            .ok_or(LowerError::UnsupportedExpression)?
                            .len(),
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Str(value),
                            ..
                        } => value.chars().count(),
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Bytes(value),
                            ..
                        } => value.len(),
                        lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings
                            .get(name)
                            .ok_or(LowerError::UnsupportedExpression)?
                        {
                            AggregateBinding::List(elements) => elements.len(),
                            AggregateBinding::StringList(elements) => elements.len(),
                            AggregateBinding::FloatList(elements) => elements.len(),
                            AggregateBinding::SingletonList(elements) => elements.len(),
                            AggregateBinding::Set(elements) => elements.len(),
                            AggregateBinding::StringSet(elements) => elements.len(),
                            AggregateBinding::FloatSet(elements) => elements.len(),
                            AggregateBinding::SingletonSet(elements) => elements.len(),
                            AggregateBinding::AggregateList(elements)
                            | AggregateBinding::AggregateSet(elements) => elements.len(),
                            AggregateBinding::Dict(entries) => entries.len(),
                            AggregateBinding::StringDict(entries) => entries.len(),
                            AggregateBinding::StringIntDict(entries) => entries.len(),
                            AggregateBinding::StringFloatDict(entries) => entries.len(),
                            AggregateBinding::StringSingletonDict(entries) => entries.len(),
                            AggregateBinding::IntStringDict(entries) => entries.len(),
                            AggregateBinding::IntSingletonDict(entries) => entries.len(),
                            AggregateBinding::FloatDict(entries) => entries.len(),
                            AggregateBinding::IntFloatDict(entries) => entries.len(),
                            AggregateBinding::FloatIntDict(entries) => entries.len(),
                            AggregateBinding::FloatStringDict(entries) => entries.len(),
                            AggregateBinding::FloatSingletonDict(entries) => entries.len(),
                            AggregateBinding::SingletonDict(entries) => entries.len(),
                            AggregateBinding::SingletonStringDict(entries) => entries.len(),
                            AggregateBinding::SingletonIntDict(entries) => entries.len(),
                            AggregateBinding::SingletonFloatDict(entries) => entries.len(),
                            AggregateBinding::Record(elements) => elements.len(),
                            AggregateBinding::MixedRecord(elements) => elements.len(),
                            AggregateBinding::StringRecord(_)
                            | AggregateBinding::FloatRecord(_)
                            | AggregateBinding::SingletonRecord(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::String(value) => value.chars().count(),
                            AggregateBinding::Bytes(value) => value.len(),
                            AggregateBinding::Range(values) => values.len(),
                            AggregateBinding::Float(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::None | AggregateBinding::Ellipsis => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                        },
                        _ => return Err(LowerError::UnsupportedExpression),
                    };
                    let value =
                        i64::try_from(length).map_err(|_| LowerError::UnsupportedExpression)?;
                    let id = result(next);
                    instructions.push(Instruction::ConstInt { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "bool"
                    ) && args.len() == 1 =>
                {
                    let value = match &args[0].value {
                        lucid_syntax::Expr::List { elements, .. } => {
                            for element in elements {
                                let _ = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                            }
                            !elements.is_empty()
                        }
                        lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let _ = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                            }
                            !elements.is_empty()
                        }
                        lucid_syntax::Expr::Dict { entries, .. } => {
                            for (key, value) in entries {
                                let _ =
                                    lower(key, bindings, aggregate_bindings, instructions, next)?;
                                let _ =
                                    lower(value, bindings, aggregate_bindings, instructions, next)?;
                            }
                            !entries.is_empty()
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let _ =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                            }
                            !fields.is_empty()
                        }
                        lucid_syntax::Expr::Call { .. } => {
                            if let Some(values) = const_range_values(&args[0].value) {
                                !values.is_empty()
                            } else if let Some(len) =
                                constant_dict_view_len(&args[0].value, aggregate_bindings)
                            {
                                len != 0
                            } else {
                                let value = lower(
                                    &args[0].value,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                                constant_value_truth(value, instructions)
                                    .ok_or(LowerError::UnsupportedExpression)?
                            }
                        }
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Str(value),
                            ..
                        } => !value.is_empty(),
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Bytes(value),
                            ..
                        } => !value.is_empty(),
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Float(value),
                            ..
                        } => *value != 0.0,
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::None,
                            ..
                        } => false,
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Ellipsis,
                            ..
                        } => true,
                        lucid_syntax::Expr::Ident { name, .. } => match aggregate_bindings
                            .get(name)
                            .ok_or(LowerError::UnsupportedExpression)?
                        {
                            AggregateBinding::List(elements) => !elements.is_empty(),
                            AggregateBinding::StringList(elements) => !elements.is_empty(),
                            AggregateBinding::AggregateList(elements) => !elements.is_empty(),
                            AggregateBinding::FloatList(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::SingletonList(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::Set(elements) => !elements.is_empty(),
                            AggregateBinding::AggregateSet(elements) => !elements.is_empty(),
                            AggregateBinding::StringSet(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::FloatSet(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::SingletonSet(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::Dict(entries) => !entries.is_empty(),
                            AggregateBinding::StringDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::StringIntDict(_)
                            | AggregateBinding::StringFloatDict(_)
                            | AggregateBinding::StringSingletonDict(_)
                            | AggregateBinding::IntStringDict(_)
                            | AggregateBinding::IntSingletonDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::FloatDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::IntFloatDict(_)
                            | AggregateBinding::FloatStringDict(_)
                            | AggregateBinding::FloatSingletonDict(_)
                            | AggregateBinding::FloatIntDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::SingletonDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::SingletonStringDict(_)
                            | AggregateBinding::SingletonIntDict(_)
                            | AggregateBinding::SingletonFloatDict(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::Record(elements) => !elements.is_empty(),
                            AggregateBinding::MixedRecord(elements) => !elements.is_empty(),
                            AggregateBinding::StringRecord(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::FloatRecord(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::SingletonRecord(_) => {
                                return Err(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::String(value) => !value.is_empty(),
                            AggregateBinding::Bytes(value) => !value.is_empty(),
                            AggregateBinding::Range(values) => !values.is_empty(),
                            AggregateBinding::Float(value) => *value != 0.0,
                            AggregateBinding::None => false,
                            AggregateBinding::Ellipsis => true,
                        },
                        expr if constant_float(expr, aggregate_bindings).is_some() => {
                            constant_float(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                != 0.0
                        }
                        expr if constant_string(expr, aggregate_bindings).is_some() => {
                            !constant_string(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .is_empty()
                        }
                        _ => {
                            let value = lower(
                                &args[0].value,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )?;
                            constant_value_truth(value, instructions)
                                .ok_or(LowerError::UnsupportedExpression)?
                        }
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "int"
                    ) && args.len() == 1 =>
                {
                    let value = match &args[0].value {
                        expr if constant_string(expr, aggregate_bindings).is_some() => {
                            constant_string(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                                .trim()
                                .parse::<i64>()
                                .map_err(|_| LowerError::UnsupportedExpression)?
                        }
                        _ => {
                            let value = lower(
                                &args[0].value,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )?;
                            if let Some(value) = constant_int(value, instructions) {
                                value
                            } else {
                                i64::from(
                                    constant_value_truth(value, instructions)
                                        .ok_or(LowerError::UnsupportedExpression)?,
                                )
                            }
                        }
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstInt { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "abs"
                    ) && args.len() == 1 =>
                {
                    let value = lower(
                        &args[0].value,
                        bindings,
                        aggregate_bindings,
                        instructions,
                        next,
                    )?;
                    let value = constant_int(value, instructions)
                        .and_then(i64::checked_abs)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let id = result(next);
                    instructions.push(Instruction::ConstInt { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "min" || name == "max"
                    ) && args.len() == 1 =>
                {
                    let mut values = Vec::new();
                    let mut add_value =
                        |value: ValueId, instructions: &[Instruction]| -> Result<(), LowerError> {
                            values.push(
                                constant_int(value, instructions)
                                    .ok_or(LowerError::UnsupportedExpression)?,
                            );
                            Ok(())
                        };
                    match &args[0].value {
                        lucid_syntax::Expr::List { elements, .. }
                        | lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let value = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                                add_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let value =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                                add_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Call { .. } => {
                            if let Some(elements) = lower_int_dict_view_elements(
                                &args[0].value,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )? {
                                for value in elements {
                                    add_value(value, instructions)?;
                                }
                            } else {
                                values.extend(
                                    const_range_values(&args[0].value)
                                        .ok_or(LowerError::UnsupportedExpression)?,
                                );
                            }
                        }
                        expr if constant_bytes(expr, aggregate_bindings).is_some() => {
                            values.extend(
                                constant_bytes(expr, aggregate_bindings)
                                    .ok_or(LowerError::UnsupportedExpression)?
                                    .into_iter()
                                    .map(i64::from),
                            );
                        }
                        lucid_syntax::Expr::Ident { name, .. } => {
                            match aggregate_bindings
                                .get(name)
                                .ok_or(LowerError::UnsupportedExpression)?
                            {
                                AggregateBinding::List(elements)
                                | AggregateBinding::Set(elements) => {
                                    for value in elements {
                                        add_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Record(elements) => {
                                    for value in elements {
                                        add_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Range(range_values) => {
                                    values.extend(range_values.iter().copied());
                                }
                                AggregateBinding::Bytes(bytes) => {
                                    values.extend(bytes.iter().map(|value| i64::from(*value)));
                                }
                                _ => return Err(LowerError::UnsupportedExpression),
                            }
                        }
                        _ => return Err(LowerError::UnsupportedExpression),
                    }
                    let is_min = matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "min"
                    );
                    let value = if is_min {
                        values.into_iter().min()
                    } else {
                        values.into_iter().max()
                    }
                    .ok_or(LowerError::UnsupportedExpression)?;
                    let id = result(next);
                    instructions.push(Instruction::ConstInt { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "min" || name == "max"
                    ) && !args.is_empty() =>
                {
                    let mut values = Vec::with_capacity(args.len());
                    for arg in args {
                        let value =
                            lower(&arg.value, bindings, aggregate_bindings, instructions, next)?;
                        values.push(
                            constant_int(value, instructions)
                                .ok_or(LowerError::UnsupportedExpression)?,
                        );
                    }
                    let is_min = matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "min"
                    );
                    let value = if is_min {
                        values.into_iter().min()
                    } else {
                        values.into_iter().max()
                    }
                    .ok_or(LowerError::UnsupportedExpression)?;
                    let id = result(next);
                    instructions.push(Instruction::ConstInt { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "sum"
                    ) && (args.len() == 1 || args.len() == 2) =>
                {
                    let mut total = if let Some(start) = args.get(1) {
                        let value = lower(
                            &start.value,
                            bindings,
                            aggregate_bindings,
                            instructions,
                            next,
                        )?;
                        constant_int(value, instructions)
                            .ok_or(LowerError::UnsupportedExpression)?
                    } else {
                        0
                    };
                    let mut add_value =
                        |value: ValueId, instructions: &[Instruction]| -> Result<(), LowerError> {
                            let value = constant_int(value, instructions)
                                .ok_or(LowerError::UnsupportedExpression)?;
                            total = total
                                .checked_add(value)
                                .ok_or(LowerError::UnsupportedExpression)?;
                            Ok(())
                        };
                    match &args[0].value {
                        lucid_syntax::Expr::List { elements, .. }
                        | lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let value = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                                add_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let value =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                                add_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Call { .. } => {
                            if let Some(elements) = lower_int_dict_view_elements(
                                &args[0].value,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )? {
                                for value in elements {
                                    add_value(value, instructions)?;
                                }
                            } else {
                                for value in const_range_values(&args[0].value)
                                    .ok_or(LowerError::UnsupportedExpression)?
                                {
                                    total = total
                                        .checked_add(value)
                                        .ok_or(LowerError::UnsupportedExpression)?;
                                }
                            }
                        }
                        expr if constant_bytes(expr, aggregate_bindings).is_some() => {
                            for value in constant_bytes(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?
                            {
                                total = total
                                    .checked_add(i64::from(value))
                                    .ok_or(LowerError::UnsupportedExpression)?;
                            }
                        }
                        lucid_syntax::Expr::Ident { name, .. } => {
                            match aggregate_bindings
                                .get(name)
                                .ok_or(LowerError::UnsupportedExpression)?
                            {
                                AggregateBinding::List(elements)
                                | AggregateBinding::Set(elements) => {
                                    for value in elements {
                                        add_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Record(elements) => {
                                    for value in elements {
                                        add_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Dict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringIntDict(_)
                                | AggregateBinding::StringFloatDict(_)
                                | AggregateBinding::StringSingletonDict(_)
                                | AggregateBinding::IntStringDict(_)
                                | AggregateBinding::IntSingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::IntFloatDict(_)
                                | AggregateBinding::FloatStringDict(_)
                                | AggregateBinding::FloatSingletonDict(_)
                                | AggregateBinding::FloatIntDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonStringDict(_)
                                | AggregateBinding::SingletonIntDict(_)
                                | AggregateBinding::SingletonFloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::MixedRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::AggregateList(_)
                                | AggregateBinding::AggregateSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::String(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::Bytes(values) => {
                                    for value in values {
                                        total = total
                                            .checked_add(i64::from(*value))
                                            .ok_or(LowerError::UnsupportedExpression)?;
                                    }
                                }
                                AggregateBinding::Range(values) => {
                                    for value in values {
                                        total = total
                                            .checked_add(*value)
                                            .ok_or(LowerError::UnsupportedExpression)?;
                                    }
                                }
                                AggregateBinding::Float(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::None | AggregateBinding::Ellipsis => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                            }
                        }
                        _ => return Err(LowerError::UnsupportedExpression),
                    }
                    let id = result(next);
                    instructions.push(Instruction::ConstInt {
                        result: id,
                        value: total,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Call { func, args, .. }
                    if matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "all" || name == "any"
                    ) && args.len() == 1 =>
                {
                    let is_all = matches!(
                        func.as_ref(),
                        lucid_syntax::Expr::Ident { name, .. } if name == "all"
                    );
                    let mut seen_any = false;
                    let mut result_value = is_all;
                    let mut fold_value =
                        |value: ValueId, instructions: &[Instruction]| -> Result<(), LowerError> {
                            let truth = constant_value_truth(value, instructions)
                                .ok_or(LowerError::UnsupportedExpression)?;
                            seen_any = true;
                            if is_all {
                                result_value &= truth;
                            } else {
                                result_value |= truth;
                            }
                            Ok(())
                        };
                    match &args[0].value {
                        lucid_syntax::Expr::List { elements, .. }
                        | lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let value = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                                fold_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let value =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                                fold_value(value, instructions)?;
                            }
                        }
                        expr if constant_bytes(expr, aggregate_bindings).is_some() => {
                            let values = constant_bytes(expr, aggregate_bindings)
                                .ok_or(LowerError::UnsupportedExpression)?;
                            seen_any |= !values.is_empty();
                            if is_all {
                                result_value &= values.iter().all(|value| *value != 0);
                            } else {
                                result_value |= values.iter().any(|value| *value != 0);
                            }
                        }
                        lucid_syntax::Expr::Call { .. } => {
                            if let Some(elements) = lower_int_dict_view_elements(
                                &args[0].value,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )? {
                                for value in elements {
                                    fold_value(value, instructions)?;
                                }
                            } else if let Some(values) = const_range_values(&args[0].value) {
                                seen_any |= !values.is_empty();
                                if is_all {
                                    result_value &= values.iter().all(|value| *value != 0);
                                } else {
                                    result_value |= values.iter().any(|value| *value != 0);
                                }
                            } else {
                                return Err(LowerError::UnsupportedExpression);
                            }
                        }
                        lucid_syntax::Expr::Ident { name, .. } => {
                            match aggregate_bindings
                                .get(name)
                                .ok_or(LowerError::UnsupportedExpression)?
                            {
                                AggregateBinding::List(elements)
                                | AggregateBinding::Set(elements) => {
                                    for value in elements {
                                        fold_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Record(elements) => {
                                    for value in elements {
                                        fold_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Dict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringIntDict(_)
                                | AggregateBinding::StringFloatDict(_)
                                | AggregateBinding::StringSingletonDict(_)
                                | AggregateBinding::IntStringDict(_)
                                | AggregateBinding::IntSingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::IntFloatDict(_)
                                | AggregateBinding::FloatStringDict(_)
                                | AggregateBinding::FloatSingletonDict(_)
                                | AggregateBinding::FloatIntDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonStringDict(_)
                                | AggregateBinding::SingletonIntDict(_)
                                | AggregateBinding::SingletonFloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::MixedRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::AggregateList(_)
                                | AggregateBinding::AggregateSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::String(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::Bytes(values) => {
                                    seen_any |= !values.is_empty();
                                    if is_all {
                                        result_value &= values.iter().all(|value| *value != 0);
                                    } else {
                                        result_value |= values.iter().any(|value| *value != 0);
                                    }
                                }
                                AggregateBinding::Range(values) => {
                                    seen_any |= !values.is_empty();
                                    if is_all {
                                        result_value &= values.iter().all(|value| *value != 0);
                                    } else {
                                        result_value |= values.iter().any(|value| *value != 0);
                                    }
                                }
                                AggregateBinding::Float(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::None | AggregateBinding::Ellipsis => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                            }
                        }
                        _ => return Err(LowerError::UnsupportedExpression),
                    }
                    if !seen_any && !is_all {
                        result_value = false;
                    }
                    let id = result(next);
                    instructions.push(Instruction::ConstBool {
                        result: id,
                        value: result_value,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Index { value, index, .. } => {
                    if let Some(index_key) = constant_float(index, aggregate_bindings) {
                        let entries = constant_float_int_dict(value, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let value = entries
                            .iter()
                            .find_map(|(key, value)| (key == &index_key).then_some(*value))
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let id = result(next);
                        instructions.push(Instruction::ConstInt { result: id, value });
                        return Ok(id);
                    }
                    if let Some(index_key) = constant_string(index, aggregate_bindings) {
                        let entries = constant_string_int_dict(value, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let value = entries
                            .iter()
                            .find_map(|(key, value)| (key == &index_key).then_some(*value))
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let id = result(next);
                        instructions.push(Instruction::ConstInt { result: id, value });
                        return Ok(id);
                    }
                    if let Some(index_key) = constant_singleton(index, aggregate_bindings) {
                        let entries = constant_singleton_int_dict(value, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let value = entries
                            .iter()
                            .find_map(|(key, value)| (key == &index_key).then_some(*value))
                            .ok_or(LowerError::UnsupportedExpression)?;
                        let id = result(next);
                        instructions.push(Instruction::ConstInt { result: id, value });
                        return Ok(id);
                    }
                    let index_value =
                        lower(index, bindings, aggregate_bindings, instructions, next)?;
                    let raw_index = constant_int(index_value, instructions)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let select_sequence = |len: usize| {
                        let len = i64::try_from(len).ok()?;
                        let index = if raw_index < 0 {
                            len.checked_add(raw_index)?
                        } else {
                            raw_index
                        };
                        let index = usize::try_from(index).ok()?;
                        (index < usize::try_from(len).ok()?).then_some(index)
                    };
                    let select_mapping =
                        |entries: &[(ValueId, ValueId)], instructions: &[Instruction]| {
                            entries.iter().find_map(|(key, value)| {
                                (constant_int(*key, instructions) == Some(raw_index))
                                    .then_some(*value)
                            })
                        };
                    if let Some(aggregate) = aggregate_expr_binding(value, aggregate_bindings) {
                        match aggregate {
                            AggregateBinding::Record(elements) => {
                                let selected = select_sequence(elements.len())
                                    .ok_or(LowerError::UnsupportedExpression)?;
                                return elements
                                    .get(selected)
                                    .copied()
                                    .ok_or(LowerError::UnsupportedExpression);
                            }
                            AggregateBinding::MixedRecord(elements) => {
                                let selected = select_sequence(elements.len())
                                    .ok_or(LowerError::UnsupportedExpression)?;
                                return match elements
                                    .get(selected)
                                    .ok_or(LowerError::UnsupportedExpression)?
                                {
                                    AggregateElement::Value(value) => Ok(*value),
                                    AggregateElement::Aggregate(_) => {
                                        Err(LowerError::UnsupportedExpression)
                                    }
                                };
                            }
                            _ => {}
                        }
                    }
                    match value.as_ref() {
                        lucid_syntax::Expr::List { elements, .. } => {
                            let selected = select_sequence(elements.len())
                                .ok_or(LowerError::UnsupportedExpression)?;
                            let mut lowered_elements = Vec::with_capacity(elements.len());
                            for element in elements {
                                lowered_elements.push(lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?);
                            }
                            lowered_elements
                                .get(selected)
                                .copied()
                                .ok_or(LowerError::UnsupportedExpression)
                        }
                        lucid_syntax::Expr::Dict { entries, .. } => {
                            let mut lowered_entries = Vec::with_capacity(entries.len());
                            for (key, value) in entries {
                                let key =
                                    lower(key, bindings, aggregate_bindings, instructions, next)?;
                                let value =
                                    lower(value, bindings, aggregate_bindings, instructions, next)?;
                                lowered_entries.push((key, value));
                            }
                            select_mapping(&lowered_entries, instructions)
                                .ok_or(LowerError::UnsupportedExpression)
                        }
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Bytes(values),
                            ..
                        } => {
                            let selected = select_sequence(values.len())
                                .ok_or(LowerError::UnsupportedExpression)?;
                            let value = i64::from(
                                *values
                                    .get(selected)
                                    .ok_or(LowerError::UnsupportedExpression)?,
                            );
                            let id = result(next);
                            instructions.push(Instruction::ConstInt { result: id, value });
                            Ok(id)
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            let selected = select_sequence(fields.len())
                                .ok_or(LowerError::UnsupportedExpression)?;
                            let mut lowered_elements = Vec::with_capacity(fields.len());
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                lowered_elements.push(lower(
                                    field,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?);
                            }
                            lowered_elements
                                .get(selected)
                                .copied()
                                .ok_or(LowerError::UnsupportedExpression)
                        }
                        lucid_syntax::Expr::Ident { name, .. } => {
                            let aggregate = aggregate_bindings
                                .get(name)
                                .ok_or(LowerError::UnsupportedExpression)?;
                            match aggregate {
                                AggregateBinding::List(elements) => {
                                    let selected = select_sequence(elements.len())
                                        .ok_or(LowerError::UnsupportedExpression)?;
                                    elements
                                        .get(selected)
                                        .copied()
                                        .ok_or(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::AggregateList(_)
                                | AggregateBinding::AggregateSet(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::Set(_) => Err(LowerError::UnsupportedExpression),
                                AggregateBinding::StringSet(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::FloatSet(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::SingletonSet(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::StringList(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::FloatList(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::SingletonList(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::StringRecord(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::FloatRecord(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::SingletonRecord(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::MixedRecord(elements) => {
                                    let selected = select_sequence(elements.len())
                                        .ok_or(LowerError::UnsupportedExpression)?;
                                    match elements
                                        .get(selected)
                                        .ok_or(LowerError::UnsupportedExpression)?
                                    {
                                        AggregateElement::Value(value) => Ok(*value),
                                        AggregateElement::Aggregate(_) => {
                                            Err(LowerError::UnsupportedExpression)
                                        }
                                    }
                                }
                                AggregateBinding::Dict(entries) => {
                                    select_mapping(entries, instructions)
                                        .ok_or(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::StringDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::StringIntDict(_)
                                | AggregateBinding::StringFloatDict(_)
                                | AggregateBinding::StringSingletonDict(_)
                                | AggregateBinding::IntStringDict(_)
                                | AggregateBinding::IntSingletonDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::FloatDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::IntFloatDict(_)
                                | AggregateBinding::FloatStringDict(_)
                                | AggregateBinding::FloatSingletonDict(_)
                                | AggregateBinding::FloatIntDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::SingletonDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::SingletonStringDict(_)
                                | AggregateBinding::SingletonIntDict(_)
                                | AggregateBinding::SingletonFloatDict(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::Record(elements) => {
                                    let selected = select_sequence(elements.len())
                                        .ok_or(LowerError::UnsupportedExpression)?;
                                    elements
                                        .get(selected)
                                        .copied()
                                        .ok_or(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::String(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::Bytes(values) => {
                                    let selected = select_sequence(values.len())
                                        .ok_or(LowerError::UnsupportedExpression)?;
                                    let value = i64::from(
                                        *values
                                            .get(selected)
                                            .ok_or(LowerError::UnsupportedExpression)?,
                                    );
                                    let id = result(next);
                                    instructions.push(Instruction::ConstInt { result: id, value });
                                    Ok(id)
                                }
                                AggregateBinding::Range(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::Float(_) => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                                AggregateBinding::None | AggregateBinding::Ellipsis => {
                                    Err(LowerError::UnsupportedExpression)
                                }
                            }
                        }
                        _ => Err(LowerError::UnsupportedExpression),
                    }
                }
                lucid_syntax::Expr::IfExpr {
                    condition,
                    then_branch,
                    else_branch,
                    ..
                } => {
                    let condition = if let Some(condition) = statement_static_truth(
                        condition,
                        bindings,
                        aggregate_bindings,
                        instructions,
                    ) {
                        condition
                    } else {
                        let condition =
                            lower(condition, bindings, aggregate_bindings, instructions, next)?;
                        constant_value_truth(condition, instructions)
                            .ok_or(LowerError::UnsupportedExpression)?
                    };
                    lower(
                        if condition { then_branch } else { else_branch },
                        bindings,
                        aggregate_bindings,
                        instructions,
                        next,
                    )
                }
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Int(value),
                    ..
                } => {
                    let id = result(next);
                    instructions.push(Instruction::ConstInt {
                        result: id,
                        value: *value,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Bool(value),
                    ..
                } => {
                    let id = result(next);
                    instructions.push(Instruction::ConstBool {
                        result: id,
                        value: *value,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Pos,
                    expr,
                    ..
                } => lower(expr, bindings, aggregate_bindings, instructions, next),
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Neg,
                    expr,
                    ..
                } => {
                    let operand = lower(expr, bindings, aggregate_bindings, instructions, next)?;
                    let id = result(next);
                    instructions.push(Instruction::Neg {
                        result: id,
                        operand,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Invert,
                    expr,
                    ..
                } => {
                    let operand = lower(expr, bindings, aggregate_bindings, instructions, next)?;
                    let id = result(next);
                    instructions.push(Instruction::BitNot {
                        result: id,
                        operand,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Not,
                    expr,
                    ..
                } => {
                    let operand = lower(expr, bindings, aggregate_bindings, instructions, next)?;
                    let id = result(next);
                    instructions.push(Instruction::Not {
                        result: id,
                        operand,
                    });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } if constant_string(left, aggregate_bindings).is_some()
                    && constant_string(right, aggregate_bindings).is_some() =>
                {
                    let needle = constant_string(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let haystack = constant_string(right, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let contains = haystack.contains(&needle);
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::Eq | lucid_syntax::BinaryOp::NotEq),
                    right,
                    ..
                } if constant_binding_candidate(left, aggregate_bindings)
                    && constant_binding_candidate(right, aggregate_bindings) =>
                {
                    let left_binding = match left.as_ref() {
                        lucid_syntax::Expr::Ident { name, .. } => aggregate_bindings
                            .get(name)
                            .cloned()
                            .ok_or(LowerError::UnsupportedExpression)?,
                        _ => lower_aggregate_literal(
                            left,
                            bindings,
                            aggregate_bindings,
                            instructions,
                            next,
                        )?
                        .ok_or(LowerError::UnsupportedExpression)?,
                    };
                    let right_binding = match right.as_ref() {
                        lucid_syntax::Expr::Ident { name, .. } => aggregate_bindings
                            .get(name)
                            .cloned()
                            .ok_or(LowerError::UnsupportedExpression)?,
                        _ => lower_aggregate_literal(
                            right,
                            bindings,
                            aggregate_bindings,
                            instructions,
                            next,
                        )?
                        .ok_or(LowerError::UnsupportedExpression)?,
                    };
                    let equal = aggregate_equal(&left_binding, &right_binding, instructions)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let value = match op {
                        lucid_syntax::BinaryOp::Eq => equal,
                        lucid_syntax::BinaryOp::NotEq => !equal,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left, op, right, ..
                } if matches!(
                    op,
                    lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::Lt
                        | lucid_syntax::BinaryOp::LtEq
                        | lucid_syntax::BinaryOp::Gt
                        | lucid_syntax::BinaryOp::GtEq
                ) && constant_string(left, aggregate_bindings).is_some()
                    && constant_string(right, aggregate_bindings).is_some() =>
                {
                    let left = constant_string(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let right = constant_string(right, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let value = match op {
                        lucid_syntax::BinaryOp::Eq => left == right,
                        lucid_syntax::BinaryOp::NotEq => left != right,
                        lucid_syntax::BinaryOp::Lt => left < right,
                        lucid_syntax::BinaryOp::LtEq => left <= right,
                        lucid_syntax::BinaryOp::Gt => left > right,
                        lucid_syntax::BinaryOp::GtEq => left >= right,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left, op, right, ..
                } if matches!(
                    op,
                    lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::Lt
                        | lucid_syntax::BinaryOp::LtEq
                        | lucid_syntax::BinaryOp::Gt
                        | lucid_syntax::BinaryOp::GtEq
                ) && constant_float(left, aggregate_bindings).is_some()
                    && constant_float(right, aggregate_bindings).is_some() =>
                {
                    let left = constant_float(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let right = constant_float(right, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let value = match op {
                        lucid_syntax::BinaryOp::Eq => left == right,
                        lucid_syntax::BinaryOp::NotEq => left != right,
                        lucid_syntax::BinaryOp::Lt => left < right,
                        lucid_syntax::BinaryOp::LtEq => left <= right,
                        lucid_syntax::BinaryOp::Gt => left > right,
                        lucid_syntax::BinaryOp::GtEq => left >= right,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left, op, right, ..
                } if matches!(
                    op,
                    lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::Identity
                        | lucid_syntax::BinaryOp::NotIdentity
                        | lucid_syntax::BinaryOp::Is
                        | lucid_syntax::BinaryOp::IsNot
                ) && constant_singleton(left, aggregate_bindings).is_some()
                    && constant_singleton(right, aggregate_bindings).is_some() =>
                {
                    let equal = constant_singleton(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?
                        == constant_singleton(right, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?;
                    let value = match op {
                        lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::Identity
                        | lucid_syntax::BinaryOp::Is => equal,
                        lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::NotIdentity
                        | lucid_syntax::BinaryOp::IsNot => !equal,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } if constant_string(left, aggregate_bindings).is_some()
                    && (constant_string_list(right, aggregate_bindings).is_some()
                        || constant_string_set(right, aggregate_bindings).is_some()
                        || constant_string_dict(right, aggregate_bindings).is_some()
                        || constant_string_int_dict(right, aggregate_bindings).is_some()
                        || constant_string_float_dict(right, aggregate_bindings).is_some()
                        || constant_string_singleton_dict(right, aggregate_bindings).is_some()) =>
                {
                    let needle = constant_string(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let contains = if let Some(haystack) =
                        constant_string_list(right, aggregate_bindings)
                    {
                        haystack.contains(&needle)
                    } else if let Some(haystack) = constant_string_set(right, aggregate_bindings) {
                        haystack.contains(&needle)
                    } else if let Some(entries) =
                        constant_string_int_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_string_float_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_string_singleton_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else {
                        constant_string_dict(right, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?
                            .iter()
                            .any(|(key, _)| key == &needle)
                    };
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } if constant_float(left, aggregate_bindings).is_some()
                    && (constant_float_list(right, aggregate_bindings).is_some()
                        || constant_float_set(right, aggregate_bindings).is_some()
                        || constant_float_dict(right, aggregate_bindings).is_some()
                        || constant_float_int_dict(right, aggregate_bindings).is_some()
                        || constant_float_string_dict(right, aggregate_bindings).is_some()
                        || constant_float_singleton_dict(right, aggregate_bindings).is_some()) =>
                {
                    let needle = constant_float(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let contains = if let Some(haystack) =
                        constant_float_list(right, aggregate_bindings)
                    {
                        haystack.contains(&needle)
                    } else if let Some(haystack) = constant_float_set(right, aggregate_bindings) {
                        haystack.contains(&needle)
                    } else if let Some(entries) = constant_float_int_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_float_string_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_float_singleton_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else {
                        constant_float_dict(right, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?
                            .iter()
                            .any(|(key, _)| key == &needle)
                    };
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } if constant_singleton(left, aggregate_bindings).is_some()
                    && (constant_singleton_list(right, aggregate_bindings).is_some()
                        || constant_singleton_set(right, aggregate_bindings).is_some()
                        || constant_singleton_dict(right, aggregate_bindings).is_some()
                        || constant_singleton_string_dict(right, aggregate_bindings).is_some()
                        || constant_singleton_int_dict(right, aggregate_bindings).is_some()
                        || constant_singleton_float_dict(right, aggregate_bindings).is_some()) =>
                {
                    let needle = constant_singleton(left, aggregate_bindings)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let contains = if let Some(haystack) =
                        constant_singleton_list(right, aggregate_bindings)
                    {
                        haystack.contains(&needle)
                    } else if let Some(haystack) = constant_singleton_set(right, aggregate_bindings)
                    {
                        haystack.contains(&needle)
                    } else if let Some(entries) =
                        constant_singleton_string_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_singleton_int_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) =
                        constant_singleton_float_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else {
                        constant_singleton_dict(right, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?
                            .iter()
                            .any(|(key, _)| key == &needle)
                    };
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } if constant_index(left).is_some()
                    && (constant_int_string_dict(right, aggregate_bindings).is_some()
                        || constant_int_float_dict(right, aggregate_bindings).is_some()
                        || constant_int_singleton_dict(right, aggregate_bindings).is_some()) =>
                {
                    let needle = constant_index(left).ok_or(LowerError::UnsupportedExpression)?;
                    let contains = if let Some(entries) =
                        constant_int_string_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else if let Some(entries) = constant_int_float_dict(right, aggregate_bindings)
                    {
                        entries.iter().any(|(key, _)| key == &needle)
                    } else {
                        constant_int_singleton_dict(right, aggregate_bindings)
                            .ok_or(LowerError::UnsupportedExpression)?
                            .iter()
                            .any(|(key, _)| key == &needle)
                    };
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left,
                    op: op @ (lucid_syntax::BinaryOp::In | lucid_syntax::BinaryOp::NotIn),
                    right,
                    ..
                } => {
                    let needle = lower(left, bindings, aggregate_bindings, instructions, next)?;
                    let needle = constant_int(needle, instructions)
                        .ok_or(LowerError::UnsupportedExpression)?;
                    let contains_value = |value: ValueId,
                                          instructions: &[Instruction]|
                     -> Result<bool, LowerError> {
                        Ok(constant_int(value, instructions)
                            .ok_or(LowerError::UnsupportedExpression)?
                            == needle)
                    };
                    let mut contains = false;
                    match right.as_ref() {
                        lucid_syntax::Expr::List { elements, .. }
                        | lucid_syntax::Expr::Set { elements, .. } => {
                            for element in elements {
                                let value = lower(
                                    element,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )?;
                                contains |= contains_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Call { func, args, .. } => {
                            if let Some(values) = const_range_values(right) {
                                contains = values.contains(&needle);
                            } else if let Some(elements) = lower_int_dict_view_elements(
                                right,
                                bindings,
                                aggregate_bindings,
                                instructions,
                                next,
                            )? {
                                for value in elements {
                                    contains |= contains_value(value, instructions)?;
                                }
                            } else if matches!(
                                func.as_ref(),
                                lucid_syntax::Expr::Ident { name, .. }
                                    if name == "list" || name == "set"
                            ) && args.len() == 1
                                && args.iter().all(|arg| {
                                    arg.name.is_none()
                                        && !arg.is_spread
                                        && !arg.is_dict_spread
                                        && !arg.is_gather_spread
                                })
                            {
                                if let Some(values) = const_range_values(&args[0].value) {
                                    contains = values.contains(&needle);
                                } else if let Some(elements) = lower_int_dict_view_elements(
                                    &args[0].value,
                                    bindings,
                                    aggregate_bindings,
                                    instructions,
                                    next,
                                )? {
                                    for value in elements {
                                        contains |= contains_value(value, instructions)?;
                                    }
                                } else if let lucid_syntax::Expr::Call {
                                    func: view_func,
                                    args: view_args,
                                    ..
                                } = &args[0].value
                                {
                                    if !view_args.is_empty() {
                                        return Err(LowerError::UnsupportedExpression);
                                    }
                                    let lucid_syntax::Expr::Attribute { value, attr, .. } =
                                        view_func.as_ref()
                                    else {
                                        return Err(LowerError::UnsupportedExpression);
                                    };
                                    if !matches!(attr.as_str(), "keys" | "values") {
                                        return Err(LowerError::UnsupportedExpression);
                                    }
                                    let lucid_syntax::Expr::Dict { entries, .. } = value.as_ref()
                                    else {
                                        return Err(LowerError::UnsupportedExpression);
                                    };
                                    contains = entries.iter().any(|(key, value)| {
                                        let selected = match attr.as_str() {
                                            "keys" => key,
                                            "values" => value,
                                            _ => unreachable!(),
                                        };
                                        constant_index(selected) == Some(needle)
                                    });
                                } else {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                            } else if let lucid_syntax::Expr::Attribute { value, attr, .. } =
                                func.as_ref()
                            {
                                if !args.is_empty() || !matches!(attr.as_str(), "keys" | "values") {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let lucid_syntax::Expr::Dict { entries, .. } = value.as_ref()
                                else {
                                    return Err(LowerError::UnsupportedExpression);
                                };
                                contains = entries.iter().any(|(key, value)| {
                                    let selected = match attr.as_str() {
                                        "keys" => key,
                                        "values" => value,
                                        _ => unreachable!(),
                                    };
                                    constant_index(selected) == Some(needle)
                                });
                            } else {
                                return Err(LowerError::UnsupportedExpression);
                            }
                        }
                        lucid_syntax::Expr::Literal {
                            value: lucid_syntax::LiteralValue::Bytes(values),
                            ..
                        } => {
                            let needle = u8::try_from(needle)
                                .map_err(|_| LowerError::UnsupportedExpression)?;
                            contains = values.contains(&needle);
                        }
                        lucid_syntax::Expr::Dict { entries, .. } => {
                            for (key, value) in entries {
                                let key =
                                    lower(key, bindings, aggregate_bindings, instructions, next)?;
                                let _ =
                                    lower(value, bindings, aggregate_bindings, instructions, next)?;
                                contains |= contains_value(key, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Record { fields, .. } => {
                            for (name, field) in fields {
                                if name.is_some() {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                let value =
                                    lower(field, bindings, aggregate_bindings, instructions, next)?;
                                contains |= contains_value(value, instructions)?;
                            }
                        }
                        lucid_syntax::Expr::Ident { name, .. } => {
                            match aggregate_bindings
                                .get(name)
                                .ok_or(LowerError::UnsupportedExpression)?
                            {
                                AggregateBinding::List(elements) => {
                                    for value in elements {
                                        contains |= contains_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::Set(elements) => {
                                    for value in elements {
                                        contains |= contains_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::StringSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::Dict(entries) => {
                                    for (key, _) in entries {
                                        contains |= contains_value(*key, instructions)?;
                                    }
                                }
                                AggregateBinding::StringDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringIntDict(_)
                                | AggregateBinding::StringSingletonDict(_)
                                | AggregateBinding::StringFloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::IntStringDict(entries) => {
                                    contains = entries.iter().any(|(key, _)| *key == needle);
                                }
                                AggregateBinding::IntFloatDict(entries) => {
                                    contains = entries.iter().any(|(key, _)| *key == needle);
                                }
                                AggregateBinding::IntSingletonDict(entries) => {
                                    contains = entries.iter().any(|(key, _)| *key == needle);
                                }
                                AggregateBinding::FloatIntDict(_)
                                | AggregateBinding::FloatStringDict(_)
                                | AggregateBinding::FloatSingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonStringDict(_)
                                | AggregateBinding::SingletonIntDict(_)
                                | AggregateBinding::SingletonFloatDict(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonList(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::StringRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::FloatRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::SingletonRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::Record(elements) => {
                                    for value in elements {
                                        contains |= contains_value(*value, instructions)?;
                                    }
                                }
                                AggregateBinding::MixedRecord(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::AggregateList(_)
                                | AggregateBinding::AggregateSet(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::String(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::Bytes(values) => {
                                    let needle = u8::try_from(needle)
                                        .map_err(|_| LowerError::UnsupportedExpression)?;
                                    contains = values.contains(&needle);
                                }
                                AggregateBinding::Range(values) => {
                                    contains = values.contains(&needle);
                                }
                                AggregateBinding::Float(_) => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                                AggregateBinding::None | AggregateBinding::Ellipsis => {
                                    return Err(LowerError::UnsupportedExpression);
                                }
                            }
                        }
                        _ => return Err(LowerError::UnsupportedExpression),
                    }
                    let value = match op {
                        lucid_syntax::BinaryOp::In => contains,
                        lucid_syntax::BinaryOp::NotIn => !contains,
                        _ => unreachable!(),
                    };
                    let id = result(next);
                    instructions.push(Instruction::ConstBool { result: id, value });
                    Ok(id)
                }
                lucid_syntax::Expr::Binary {
                    left, op, right, ..
                } => {
                    let left = lower(left, bindings, aggregate_bindings, instructions, next)?;
                    let right = lower(right, bindings, aggregate_bindings, instructions, next)?;
                    let id = result(next);
                    let instruction = match op {
                        lucid_syntax::BinaryOp::Add => Instruction::Add {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Sub => Instruction::Sub {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Mul => Instruction::Mul {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Pow => Instruction::Pow {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Div => Instruction::Div {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::FloorDiv => Instruction::FloorDiv {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Mod => Instruction::Mod {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::BitAnd => Instruction::BitAnd {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::BitOr => Instruction::BitOr {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::BitXor => Instruction::BitXor {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Shl => Instruction::Shl {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Shr => Instruction::Shr {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::Identity
                        | lucid_syntax::BinaryOp::Is => Instruction::CmpEq {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::NotIdentity
                        | lucid_syntax::BinaryOp::IsNot => Instruction::CmpNe {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::LtEq => Instruction::CmpLe {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Gt => Instruction::CmpGt {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::GtEq => Instruction::CmpGe {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Lt => Instruction::CmpLt {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::And => Instruction::And {
                            result: id,
                            left,
                            right,
                        },
                        lucid_syntax::BinaryOp::Or => Instruction::Or {
                            result: id,
                            left,
                            right,
                        },
                        _ => return Err(LowerError::UnsupportedExpression),
                    };
                    instructions.push(instruction);
                    Ok(id)
                }
                _ => Err(LowerError::UnsupportedExpression),
            }
        }
        let mut last = None;
        fn visit_all(
            statements: &[lucid_syntax::Stmt],
            bindings: &mut HashMap<String, ValueId>,
            aggregate_bindings: &mut HashMap<String, AggregateBinding>,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
            last: &mut Option<ValueId>,
        ) -> Result<(), LowerError> {
            for statement in statements {
                visit(
                    statement,
                    bindings,
                    aggregate_bindings,
                    instructions,
                    next,
                    last,
                )?;
            }
            Ok(())
        }
        fn contains_return(statements: &[lucid_syntax::Stmt]) -> bool {
            statements.iter().any(|statement| match statement {
                lucid_syntax::Stmt::Return { .. } => true,
                lucid_syntax::Stmt::If {
                    then_branch,
                    elif_branches,
                    else_branch,
                    ..
                } => {
                    contains_return(then_branch)
                        || elif_branches
                            .iter()
                            .any(|(_, branch)| contains_return(branch))
                        || else_branch.as_deref().is_some_and(contains_return)
                }
                lucid_syntax::Stmt::For {
                    body, if_broken, ..
                }
                | lucid_syntax::Stmt::While {
                    body, if_broken, ..
                } => contains_return(body) || if_broken.as_deref().is_some_and(contains_return),
                lucid_syntax::Stmt::With { body, .. } => contains_return(body),
                _ => false,
            })
        }
        fn literal_int(expr: &lucid_syntax::Expr) -> Option<i64> {
            match expr {
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Int(value),
                    ..
                } => Some(*value),
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Neg,
                    expr,
                    ..
                } => literal_int(expr)?.checked_neg(),
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Pos,
                    expr,
                    ..
                } => literal_int(expr),
                _ => None,
            }
        }
        fn literal_bool(expr: &lucid_syntax::Expr) -> Option<bool> {
            match expr {
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Bool(value),
                    ..
                } => Some(*value),
                _ => None,
            }
        }
        fn constant_truth(expr: &lucid_syntax::Expr) -> Option<bool> {
            match expr {
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Bool(value),
                    ..
                } => Some(*value),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Int(value),
                    ..
                } => Some(*value != 0),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Str(value),
                    ..
                } => Some(!value.is_empty()),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::None,
                    ..
                } => Some(false),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::BigInt(value),
                    ..
                } => {
                    let digits = value.trim().trim_start_matches(['+', '-']).replace('_', "");
                    let (digits, radix) = if let Some(value) = digits
                        .strip_prefix("0x")
                        .or_else(|| digits.strip_prefix("0X"))
                    {
                        (value, 16)
                    } else if let Some(value) = digits
                        .strip_prefix("0o")
                        .or_else(|| digits.strip_prefix("0O"))
                    {
                        (value, 8)
                    } else if let Some(value) = digits
                        .strip_prefix("0b")
                        .or_else(|| digits.strip_prefix("0B"))
                    {
                        (value, 2)
                    } else {
                        (digits.as_str(), 10)
                    };
                    Some(digits.chars().any(|digit| digit.to_digit(radix) != Some(0)))
                }
                lucid_syntax::Expr::Literal {
                    value:
                        lucid_syntax::LiteralValue::Sentinel(_) | lucid_syntax::LiteralValue::Ellipsis,
                    ..
                } => Some(true),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Float(value),
                    ..
                } => Some(*value != 0.0),
                lucid_syntax::Expr::Literal {
                    value: lucid_syntax::LiteralValue::Complex(value),
                    ..
                } => Some(*value != 0.0),
                lucid_syntax::Expr::Unary {
                    op: lucid_syntax::UnaryOp::Not,
                    expr,
                    ..
                } => constant_truth(expr).map(|value| !value),
                lucid_syntax::Expr::Binary {
                    op: lucid_syntax::BinaryOp::And,
                    left,
                    right,
                    ..
                } => match constant_truth(left) {
                    Some(false) => Some(false),
                    Some(true) => constant_truth(right),
                    None => None,
                },
                lucid_syntax::Expr::Binary {
                    op: lucid_syntax::BinaryOp::Or,
                    left,
                    right,
                    ..
                } => match constant_truth(left) {
                    Some(true) => Some(true),
                    Some(false) => constant_truth(right),
                    None => None,
                },
                lucid_syntax::Expr::Binary {
                    op, left, right, ..
                } => {
                    let compare = |left: f64, right: f64| match op {
                        lucid_syntax::BinaryOp::Eq
                        | lucid_syntax::BinaryOp::Identity
                        | lucid_syntax::BinaryOp::Is => Some(left == right),
                        lucid_syntax::BinaryOp::NotEq
                        | lucid_syntax::BinaryOp::NotIdentity
                        | lucid_syntax::BinaryOp::IsNot => Some(left != right),
                        lucid_syntax::BinaryOp::Lt => Some(left < right),
                        lucid_syntax::BinaryOp::LtEq => Some(left <= right),
                        lucid_syntax::BinaryOp::Gt => Some(left > right),
                        lucid_syntax::BinaryOp::GtEq => Some(left >= right),
                        _ => None,
                    };
                    match (left.as_ref(), right.as_ref()) {
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Str(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Str(right),
                                ..
                            },
                        ) => match op {
                            lucid_syntax::BinaryOp::Eq
                            | lucid_syntax::BinaryOp::Identity
                            | lucid_syntax::BinaryOp::Is => Some(left == right),
                            lucid_syntax::BinaryOp::NotEq
                            | lucid_syntax::BinaryOp::NotIdentity
                            | lucid_syntax::BinaryOp::IsNot => Some(left != right),
                            _ => None,
                        },
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::None,
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::None,
                                ..
                            },
                        ) => match op {
                            lucid_syntax::BinaryOp::Eq
                            | lucid_syntax::BinaryOp::Identity
                            | lucid_syntax::BinaryOp::Is => Some(true),
                            lucid_syntax::BinaryOp::NotEq
                            | lucid_syntax::BinaryOp::NotIdentity
                            | lucid_syntax::BinaryOp::IsNot => Some(false),
                            _ => None,
                        },
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Sentinel(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Sentinel(right),
                                ..
                            },
                        ) => match op {
                            lucid_syntax::BinaryOp::Eq
                            | lucid_syntax::BinaryOp::Identity
                            | lucid_syntax::BinaryOp::Is => Some(left == right),
                            lucid_syntax::BinaryOp::NotEq
                            | lucid_syntax::BinaryOp::NotIdentity
                            | lucid_syntax::BinaryOp::IsNot => Some(left != right),
                            _ => None,
                        },
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Ellipsis,
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Ellipsis,
                                ..
                            },
                        ) => match op {
                            lucid_syntax::BinaryOp::Eq
                            | lucid_syntax::BinaryOp::Identity
                            | lucid_syntax::BinaryOp::Is => Some(true),
                            lucid_syntax::BinaryOp::NotEq
                            | lucid_syntax::BinaryOp::NotIdentity
                            | lucid_syntax::BinaryOp::IsNot => Some(false),
                            _ => None,
                        },
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::BigInt(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::BigInt(right),
                                ..
                            },
                        ) => {
                            let normalize = |value: &str| {
                                let value = value.trim().replace('_', "");
                                let negative = value.starts_with('-');
                                let digits =
                                    value.trim_start_matches(['+', '-']).trim_start_matches('0');
                                let digits = if digits.is_empty() { "0" } else { digits };
                                if negative && digits != "0" {
                                    format!("-{digits}")
                                } else {
                                    digits.to_string()
                                }
                            };
                            let equal = normalize(left) == normalize(right);
                            match op {
                                lucid_syntax::BinaryOp::Eq
                                | lucid_syntax::BinaryOp::Identity
                                | lucid_syntax::BinaryOp::Is => Some(equal),
                                lucid_syntax::BinaryOp::NotEq
                                | lucid_syntax::BinaryOp::NotIdentity
                                | lucid_syntax::BinaryOp::IsNot => Some(!equal),
                                _ => None,
                            }
                        }
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Bool(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Bool(right),
                                ..
                            },
                        ) => match op {
                            lucid_syntax::BinaryOp::Eq
                            | lucid_syntax::BinaryOp::Identity
                            | lucid_syntax::BinaryOp::Is => Some(left == right),
                            lucid_syntax::BinaryOp::NotEq
                            | lucid_syntax::BinaryOp::NotIdentity
                            | lucid_syntax::BinaryOp::IsNot => Some(left != right),
                            _ => None,
                        },
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Int(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Int(right),
                                ..
                            },
                        ) => compare(*left as f64, *right as f64),
                        (
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Float(left),
                                ..
                            },
                            lucid_syntax::Expr::Literal {
                                value: lucid_syntax::LiteralValue::Float(right),
                                ..
                            },
                        ) => compare(*left, *right),
                        _ => None,
                    }
                }
                _ => None,
            }
        }
        fn instruction_value(instruction: &Instruction) -> ValueId {
            match instruction {
                Instruction::Param { result, .. }
                | Instruction::ConstInt { result, .. }
                | Instruction::ConstBool { result, .. }
                | Instruction::Add { result, .. }
                | Instruction::Sub { result, .. }
                | Instruction::Mul { result, .. }
                | Instruction::Pow { result, .. }
                | Instruction::Div { result, .. }
                | Instruction::FloorDiv { result, .. }
                | Instruction::Mod { result, .. }
                | Instruction::BitAnd { result, .. }
                | Instruction::BitOr { result, .. }
                | Instruction::BitXor { result, .. }
                | Instruction::Shl { result, .. }
                | Instruction::Shr { result, .. }
                | Instruction::CmpEq { result, .. }
                | Instruction::CmpNe { result, .. }
                | Instruction::CmpLe { result, .. }
                | Instruction::CmpGt { result, .. }
                | Instruction::CmpGe { result, .. }
                | Instruction::CmpLt { result, .. }
                | Instruction::Neg { result, .. }
                | Instruction::BitNot { result, .. }
                | Instruction::Not { result, .. }
                | Instruction::And { result, .. }
                | Instruction::Or { result, .. }
                | Instruction::CheckNonZero { result, .. }
                | Instruction::Phi { result, .. } => *result,
            }
        }
        fn constant_int(value: ValueId, instructions: &[Instruction]) -> Option<i64> {
            let instruction = instructions
                .iter()
                .find(|instruction| instruction_value(instruction) == value)?;
            match instruction {
                Instruction::ConstInt { value, .. } => Some(*value),
                Instruction::ConstBool { value, .. } => Some(i64::from(*value)),
                Instruction::Add { left, right, .. } => constant_int(*left, instructions)?
                    .checked_add(constant_int(*right, instructions)?),
                Instruction::Sub { left, right, .. } => constant_int(*left, instructions)?
                    .checked_sub(constant_int(*right, instructions)?),
                Instruction::Mul { left, right, .. } => constant_int(*left, instructions)?
                    .checked_mul(constant_int(*right, instructions)?),
                Instruction::Div { left, right, .. } => {
                    let left = constant_int(*left, instructions)?;
                    let right = constant_int(*right, instructions)?;
                    (right != 0).then(|| left.checked_div(right)).flatten()
                }
                Instruction::FloorDiv { left, right, .. } => {
                    let left = constant_int(*left, instructions)?;
                    let right = constant_int(*right, instructions)?;
                    (right != 0)
                        .then(|| left.checked_div_euclid(right))
                        .flatten()
                }
                Instruction::Mod { left, right, .. } => {
                    let left = constant_int(*left, instructions)?;
                    let right = constant_int(*right, instructions)?;
                    (right != 0)
                        .then(|| left.checked_rem_euclid(right))
                        .flatten()
                }
                Instruction::Neg { operand, .. } => {
                    constant_int(*operand, instructions)?.checked_neg()
                }
                Instruction::Pow { left, right, .. } => {
                    u32::try_from(constant_int(*right, instructions)?)
                        .ok()
                        .and_then(|exponent| {
                            constant_int(*left, instructions)?.checked_pow(exponent)
                        })
                }
                Instruction::BitAnd { left, right, .. } => {
                    Some(constant_int(*left, instructions)? & constant_int(*right, instructions)?)
                }
                Instruction::BitOr { left, right, .. } => {
                    Some(constant_int(*left, instructions)? | constant_int(*right, instructions)?)
                }
                Instruction::BitXor { left, right, .. } => {
                    Some(constant_int(*left, instructions)? ^ constant_int(*right, instructions)?)
                }
                Instruction::BitNot { operand, .. } => Some(!constant_int(*operand, instructions)?),
                Instruction::Shl { left, right, .. } => {
                    let shift = u32::try_from(constant_int(*right, instructions)?).ok()?;
                    (shift < 64)
                        .then(|| constant_int(*left, instructions)?.checked_shl(shift))
                        .flatten()
                }
                Instruction::Shr { left, right, .. } => {
                    let shift = u32::try_from(constant_int(*right, instructions)?).ok()?;
                    (shift < 64)
                        .then(|| Some(constant_int(*left, instructions)? >> shift))
                        .flatten()
                }
                _ => None,
            }
        }
        fn push_const_int(
            value: i64,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> ValueId {
            let id = ValueId(*next);
            *next += 1;
            instructions.push(Instruction::ConstInt { result: id, value });
            id
        }
        fn lower_int_dict_view_elements(
            expr: &lucid_syntax::Expr,
            bindings: &HashMap<String, ValueId>,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> Result<Option<Vec<ValueId>>, LowerError> {
            let Some((value, attr)) = dict_view_parts(expr) else {
                return Ok(None);
            };
            if let lucid_syntax::Expr::Dict { entries, .. } = value {
                let mut elements = Vec::with_capacity(entries.len());
                for (key, value) in entries {
                    let selected = match attr {
                        "keys" => {
                            let _ = lower(value, bindings, aggregate_bindings, instructions, next)?;
                            key
                        }
                        "values" => {
                            let _ = lower(key, bindings, aggregate_bindings, instructions, next)?;
                            value
                        }
                        _ => unreachable!(),
                    };
                    elements.push(lower(
                        selected,
                        bindings,
                        aggregate_bindings,
                        instructions,
                        next,
                    )?);
                }
                return Ok(Some(elements));
            }
            let lucid_syntax::Expr::Ident { name, .. } = value else {
                return Ok(None);
            };
            let Some(aggregate) = aggregate_bindings.get(name) else {
                return Ok(None);
            };
            let elements = match (attr, aggregate) {
                ("keys", AggregateBinding::Dict(entries)) => {
                    entries.iter().map(|(key, _)| *key).collect()
                }
                ("values", AggregateBinding::Dict(entries)) => {
                    entries.iter().map(|(_, value)| *value).collect()
                }
                ("keys", AggregateBinding::IntStringDict(entries)) => entries
                    .iter()
                    .map(|(key, _)| push_const_int(*key, instructions, next))
                    .collect(),
                ("keys", AggregateBinding::IntFloatDict(entries)) => entries
                    .iter()
                    .map(|(key, _)| push_const_int(*key, instructions, next))
                    .collect(),
                ("keys", AggregateBinding::IntSingletonDict(entries)) => entries
                    .iter()
                    .map(|(key, _)| push_const_int(*key, instructions, next))
                    .collect(),
                ("values", AggregateBinding::StringIntDict(entries)) => entries
                    .iter()
                    .map(|(_, value)| push_const_int(*value, instructions, next))
                    .collect(),
                ("values", AggregateBinding::FloatIntDict(entries)) => entries
                    .iter()
                    .map(|(_, value)| push_const_int(*value, instructions, next))
                    .collect(),
                ("values", AggregateBinding::SingletonIntDict(entries)) => entries
                    .iter()
                    .map(|(_, value)| push_const_int(*value, instructions, next))
                    .collect(),
                _ => return Ok(None),
            };
            Ok(Some(elements))
        }
        enum AggregateLoopValue {
            Value(ValueId),
            Aggregate(AggregateBinding),
        }
        fn singleton_aggregate(value: SingletonBinding) -> AggregateBinding {
            match value {
                SingletonBinding::None => AggregateBinding::None,
                SingletonBinding::Ellipsis => AggregateBinding::Ellipsis,
            }
        }
        fn int_record_element(
            value: i64,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> AggregateElement {
            AggregateElement::Value(push_const_int(value, instructions, next))
        }
        fn aggregate_record_element(aggregate: AggregateBinding) -> AggregateElement {
            AggregateElement::Aggregate(aggregate)
        }
        fn aggregate_element_from_expr(
            expr: &lucid_syntax::Expr,
            bindings: &HashMap<String, ValueId>,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> Result<AggregateElement, LowerError> {
            if let Some(aggregate) =
                lower_aggregate_literal(expr, bindings, aggregate_bindings, instructions, next)?
            {
                Ok(AggregateElement::Aggregate(aggregate))
            } else {
                Ok(AggregateElement::Value(lower(
                    expr,
                    bindings,
                    aggregate_bindings,
                    instructions,
                    next,
                )?))
            }
        }
        fn item_record_from_elements(
            key: AggregateElement,
            value: AggregateElement,
        ) -> AggregateBinding {
            match (key, value) {
                (AggregateElement::Value(key), AggregateElement::Value(value)) => {
                    AggregateBinding::Record(vec![key, value])
                }
                (key, value) => AggregateBinding::MixedRecord(vec![key, value]),
            }
        }
        fn aggregate_loop_value_binding(value: AggregateLoopValue) -> Option<AggregateBinding> {
            match value {
                AggregateLoopValue::Aggregate(aggregate) => Some(aggregate),
                AggregateLoopValue::Value(_) => None,
            }
        }
        fn dict_item_records(
            expr: &lucid_syntax::Expr,
            bindings: &HashMap<String, ValueId>,
            aggregate_bindings: &HashMap<String, AggregateBinding>,
            instructions: &mut Vec<Instruction>,
            next: &mut u32,
        ) -> Result<Option<Vec<AggregateBinding>>, LowerError> {
            let Some((value, attr)) = dict_view_parts_with_items(expr) else {
                return Ok(None);
            };
            if attr != "items" {
                return Ok(None);
            }
            if let lucid_syntax::Expr::Dict { entries, .. } = value {
                let mut records = Vec::with_capacity(entries.len());
                for (key, value) in entries {
                    let key = aggregate_element_from_expr(
                        key,
                        bindings,
                        aggregate_bindings,
                        instructions,
                        next,
                    )?;
                    let value = aggregate_element_from_expr(
                        value,
                        bindings,
                        aggregate_bindings,
                        instructions,
                        next,
                    )?;
                    records.push(item_record_from_elements(key, value));
                }
                return Ok(Some(records));
            }
            let Some(values) =
                aggregate_dict_view_loop_values(expr, aggregate_bindings, instructions, next)
            else {
                return Ok(None);
            };
            values
                .into_iter()
                .map(aggregate_loop_value_binding)
                .collect::<Option<Vec<_>>>()
                .map(Some)
                .ok_or(LowerError::UnsupportedExpression)
        }
