    #[test]
    fn module_lowering_owns_assignment_selection() {
        let module = lucid_syntax::parse("value = 6 * 7\n").unwrap();
        assert_eq!(
            Function::from_module(&module).unwrap().execute(),
            Ok(Some(42))
        );
        let empty = lucid_syntax::parse("pass\n").unwrap();
        assert_eq!(Function::from_module(&empty).unwrap().execute(), Ok(None));
        let module = lucid_syntax::parse("first = 1\nsecond = first + 2\n").unwrap();
        assert_eq!(
            Function::from_module(&module).unwrap().execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse("value = 4\nreturn value + 1\n").unwrap();
        assert_eq!(
            Function::from_module(&module).unwrap().execute(),
            Ok(Some(5))
        );
        let module = lucid_syntax::parse("while false:\n    pass\nvalue = 7\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("statically false loops should fold in linear lowering")
                .execute(),
            Ok(Some(7))
        );
        let module = lucid_syntax::parse("for item in []:\n    pass\nvalue = 8\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty literal loops should fold in linear lowering")
                .execute(),
            Ok(Some(8))
        );
        let module = lucid_syntax::parse("for item in []:\n    return 1\nvalue = 9\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty literal loops should ignore unreachable returns")
                .execute(),
            Ok(Some(9))
        );
        let module = lucid_syntax::parse("for item in b\"\":\n    return 1\nvalue = 10\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty bytes loops should ignore unreachable returns")
                .execute(),
            Ok(Some(10))
        );
        let module =
            lucid_syntax::parse("for item in \"\".chars:\n    return 1\nvalue = 11\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty chars loops should ignore unreachable returns")
                .execute(),
            Ok(Some(11))
        );
        let module = lucid_syntax::parse(
            "value = 8\nfor item in []:\n    value = 1\nif_broken:\n    value = 2\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty literal loop if_broken should not run")
                .execute(),
            Ok(Some(8))
        );
        let module = lucid_syntax::parse(
            "value = 7\nwhile false:\n    value = 1\nif_broken:\n    value = 2\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("statically false while if_broken should not run")
                .execute(),
            Ok(Some(7))
        );
        let module =
            lucid_syntax::parse("for item in range(0, 1, -1):\n    pass\nvalue = 9\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty range loops should fold in linear lowering")
                .execute(),
            Ok(Some(9))
        );
        let module =
            lucid_syntax::parse("for item in range(0):\n    return 1\nvalue = 11\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty range loops should ignore unreachable returns")
                .execute(),
            Ok(Some(11))
        );
        let module = lucid_syntax::parse("for item in range(-1):\n    pass\nvalue = 10\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("negative-stop range loops should fold in linear lowering")
                .execute(),
            Ok(Some(10))
        );
        let module =
            lucid_syntax::parse("for item in [1, 2, 3]:\n    value = item\nvalue = value + 1\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant list loops should unroll in linear lowering")
                .execute(),
            Ok(Some(4))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in [1, 2, 3]:\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant list accumulation should unroll in order")
                .execute(),
            Ok(Some(6))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in (1, 2, 3):\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant tuple accumulation should unroll in order")
                .execute(),
            Ok(Some(6))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in b\"abc\":\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant bytes loops should expose integer byte values")
                .execute(),
            Ok(Some(294))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor ch in \"abc\".chars:\n    value = value + len(ch)\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant chars loops should expose one-character strings")
                .execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse("for item in ():\n    return 1\nvalue = 7\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("empty tuple loops should fold away")
                .execute(),
            Ok(Some(7))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in {1, 2, 3}:\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant set loops should unroll in order")
                .execute(),
            Ok(Some(6))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in {1: 2, 3: 4}:\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary loops should iterate keys")
                .execute(),
            Ok(Some(4))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor item in {1: 10, 2: 20}.keys():\n    value = value + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary key views should iterate keys")
                .execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1: 10, 2: 20}\nfor item in pairs.keys():\n    value = value + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound dictionary key views should iterate keys")
                .execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor item in {1: 10, 2: 20}.values():\n    value = value + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary value views should iterate values")
                .execute(),
            Ok(Some(30))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1: 10, 2: 20}\nfor item in pairs.values():\n    value = value + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound dictionary value views should iterate values")
                .execute(),
            Ok(Some(30))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor item in {1: 10, 2: 20}.items():\n    value = value + item[0] + item[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary item views should iterate key-value records")
                .execute(),
            Ok(Some(33))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1: 10, 2: 20}\nfor item in pairs.items():\n    value = value + item[0] + item[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound dictionary item views should iterate key-value records")
                .execute(),
            Ok(Some(33))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {\"a\": \"bc\", \"de\": \"f\"}\nfor item in pairs.items():\n    value = value + len(item[0]) + len(item[1])\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound string dictionary item views should iterate key-value records")
                .execute(),
            Ok(Some(6))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1.5: 2.5, 3.5: 4.5}\nfor item in pairs.items():\n    value = value + int(item[0] < item[1])\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound float dictionary item views should iterate key-value records")
                .execute(),
            Ok(Some(2))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {\"a\": 10, \"bc\": 20}\nfor item in pairs.items():\n    value = value + len(item[0]) + item[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound string-int dictionary item views should iterate mixed records")
                .execute(),
            Ok(Some(33))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1: \"a\", 2: \"bc\"}\nfor item in pairs.items():\n    value = value + item[0] + len(item[1])\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound int-string dictionary item views should iterate mixed records")
                .execute(),
            Ok(Some(6))
        );
        let module = lucid_syntax::parse(
            "total = 0\nfor key, item in {1: 10, 2: 20}.items():\n    total = total + key + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary item views should destructure key-value records")
                .execute(),
            Ok(Some(33))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {\"a\": 10, \"bc\": 20}\nfor key, item in pairs.items():\n    value = value + len(key) + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound mixed dictionary item views should destructure key-value records")
                .execute(),
            Ok(Some(33))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor item in {1: \"a\", 2: \"bc\"}.values():\n    value = value + len(item)\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant dictionary string value views should bind aggregates")
                .execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse(
            "value = 0\npairs = {1: \"a\", 2: \"bc\"}\nfor item in pairs.values():\n    value = value + len(item)\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("bound dictionary string value views should bind aggregates")
                .execute(),
            Ok(Some(3))
        );
        let module = lucid_syntax::parse("for item in {1: 1 / 0}:\n    pass\nvalue = 4\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("dictionary value expressions should lower")
                .execute(),
            Err(ExecuteError::DivisionByZero)
        );
        let module =
            lucid_syntax::parse("value = 0\nfor _ in [1, 2, 3]:\n    value = value + 1\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("wildcard constant loops should discard the binding")
                .execute(),
            Ok(Some(3))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor _ in (1, 2, 3):\n    value = value + 1\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("wildcard tuple loops should discard the binding")
                .execute(),
            Ok(Some(3))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor _ in b\"abc\":\n    value = value + 1\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("wildcard bytes loops should discard the binding")
                .execute(),
            Ok(Some(3))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor _ in \"abc\".chars:\n    value = value + 1\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("wildcard chars loops should discard the binding")
                .execute(),
            Ok(Some(3))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor 2 in [1, 2, 3, 2]:\n    value = value + 1\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("literal constant loop patterns should filter elements")
                .execute(),
            Ok(Some(2))
        );
        let module =
            lucid_syntax::parse("for 4 in [1, 2, 3]:\n    return 1\nvalue = 12\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("literal loop patterns should ignore unreachable returns")
                .execute(),
            Ok(Some(12))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor 2 in (1, 2, 3, 2):\n    value = value + 1\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("literal tuple loop patterns should filter elements")
                .execute(),
            Ok(Some(2))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor 98 in b\"abcba\":\n    value = value + 1\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("literal bytes loop patterns should filter byte values")
                .execute(),
            Ok(Some(2))
        );
        let module =
            lucid_syntax::parse("for 300 in b\"abc\":\n    return 1\nvalue = 14\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("out-of-range bytes loop patterns should not match")
                .execute(),
            Ok(Some(14))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor \"b\" in \"abcba\".chars:\n    value = value + 1\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("literal chars loop patterns should filter characters")
                .execute(),
            Ok(Some(2))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor true in [false, true, true]:\n    value = value + 1\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("boolean literal loop patterns should filter elements")
                .execute(),
            Ok(Some(2))
        );
        let module =
            lucid_syntax::parse("for true in [false]:\n    return 1\nvalue = 13\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("boolean literal loop patterns should ignore unreachable returns")
                .execute(),
            Ok(Some(13))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor true in (false, true, true):\n    value = value + 1\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("boolean literal tuple loop patterns should filter elements")
                .execute(),
            Ok(Some(2))
        );
        let module =
            lucid_syntax::parse("value = 0\nfor item in range(1, 4):\n    value = value + item\n")
                .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("constant range loops should unroll in order")
                .execute(),
            Ok(Some(6))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor pair in enumerate([10, 20], 3):\n    value = value + pair[0] + pair[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("enumerate over constant integer lists should expose index-value records")
                .execute(),
            Ok(Some(37))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor i, item in enumerate(range(2), 5):\n    value = value + i * 10 + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("enumerate over constant ranges should support tuple targets")
                .execute(),
            Ok(Some(111))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor pair in enumerate(b\"AB\"):\n    value = value + pair[0] + pair[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("enumerate over constant bytes should expose byte values")
                .execute(),
            Ok(Some(132))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor pair in zip([1, 2], [10, 20]):\n    value = value + pair[0] * pair[1]\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("zip over constant integer lists should expose value records")
                .execute(),
            Ok(Some(50))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor left, right in zip(range(2), b\"AB\"):\n    value = value + left + right\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("zip over constant ranges and bytes should support tuple targets")
                .execute(),
            Ok(Some(132))
        );
        let module = lucid_syntax::parse(
            "value = 0\nfor item in range(1 + 1, 2 * 3, 1 << 1):\n    value = value + item\n",
        )
        .unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("arithmetic constant range bounds should unroll")
                .execute(),
            Ok(Some(6))
        );
        let module =
            lucid_syntax::parse("for item in range(2048):\n    pass\nvalue = 13\n").unwrap();
        assert!(
            Function::from_module(&module).is_err(),
            "oversized constant ranges must not be unrolled without a bound"
        );
        let module = lucid_syntax::parse("assert(true)\nvalue = 11\n").unwrap();
        assert_eq!(
            Function::from_module(&module)
                .expect("a statically true assertion should be removed")
                .execute(),
            Ok(Some(11))
        );
        let module = lucid_syntax::parse("assert(false)\nvalue = 12\n").unwrap();
        assert!(
            Function::from_module(&module).is_err(),
            "a statically false assertion must not be erased"
        );
        let module = lucid_syntax::parse("return\n").unwrap();
        assert_eq!(Function::from_module(&module).unwrap().execute(), Ok(None));
    }

