    #[test]
    fn linear_module_lowering_indexes_constant_list_aggregates() {
        let module = lucid_syntax::parse("values = [40, 41, 42]\nreturn values[2]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse("return [40, 41, 42][-1]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse(
            "base = 40\nvalues = [base, base + 1, base + 2]\nreturn values[1]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(41)));

        let module =
            lucid_syntax::parse("values = [item + 40 for item in range(3)]\nreturn values[2]\n")
                .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse(
            "values = [item * 10 for item in [1, 2, 3] if item != 2]\nreturn len(values) + values[1]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(32)));

        let module =
            lucid_syntax::parse("values = {item + 1 for item in range(3)}\nreturn len(values)\n")
                .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(3)));
    }

    #[test]
    fn linear_module_lowering_indexes_constant_dict_aggregates() {
        let module = lucid_syntax::parse("values = {1: 40, 2: 42}\nreturn values[2]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module =
            lucid_syntax::parse("values = dict({1: 40, 2: 42})\nreturn values[2]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module =
            lucid_syntax::parse("values = dict([[1, 40], [2, 42]])\nreturn values[2]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module =
            lucid_syntax::parse("values = dict(((1, 40), (2, 42)))\nreturn values[1]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(40)));

        let module =
            lucid_syntax::parse("values = dict({1: 40, 2: 42}.items())\nreturn values[2]\n")
                .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse(
            "pairs = {1: 40, 2: 42}\nvalues = dict(pairs.items())\nreturn values[2]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse(
            "pairs = {1: 40, 2: 42}\nvalues = {key: value + 1 for key, value in pairs.items()}\nreturn values[2]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(43)));

        let module = lucid_syntax::parse(
            "pairs = {1: 40, 2: 42}\nvalues = {key: value for key, value in pairs.items() if key == 2}\nreturn len(values) + values[2]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(43)));

        let module = lucid_syntax::parse(
            "pairs = {1: 40, 2: 42}\nitems = list(pairs.items())\nreturn items[1][0] + items[1][1]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(44)));

        let module = lucid_syntax::parse(
            "pairs = {\"a\": 40, \"bc\": 42}\nitems = list(pairs.items())\nreturn len(items[1][0]) + items[1][1]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(44)));

        let module = lucid_syntax::parse(
            "total = 0\npairs = {\"a\": 40, \"bc\": 42}\nitems = list(pairs.items())\nfor item in items:\n    total = total + len(item[0]) + item[1]\nreturn total\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(85)));

        let module = lucid_syntax::parse(
            "total = 0\npairs = {\"a\": 40, \"bc\": 42}\nitems = list(pairs.items())\nfor key, value in items:\n    total = total + len(key) + value\nreturn total\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(85)));

        let module = lucid_syntax::parse(
            "pairs = {1: 40, 2: 42}\nitems = set(pairs.items())\nreturn len(items)\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(2)));

        let module = lucid_syntax::parse("return {1: 40, 2: 42}[1 + 1]\n").unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));

        let module = lucid_syntax::parse(
            "base = 40\nvalues = {base - 39: base + 1, base - 38: base + 2}\nreturn values[2]\n",
        )
        .unwrap();
        let function = Function::from_module_linear(&module).unwrap();
        assert_eq!(function.execute(), Ok(Some(42)));
    }

